css:
/* Story playback */
.panel section.playback { border-bottom:1px solid var(--rule); padding-bottom:16px; gap:7px; }
.playback select { font:inherit; font-size:13px; padding:6px 7px; width:100%; min-width:0; min-height:34px; border:1px solid var(--rule); border-radius:3px; background:var(--paper); color:var(--ink); }
.playback .ap-label { display:block; font-size:12px; line-height:1.3; color:var(--muted); }
.playback > h2 { order:0; }
.ap-caption { display:contents; }
.ap-caption[hidden] { display:none !important; }
.ap-caption .ap-title { order:1; margin:0; font-family:var(--f-display); font-size:19px; font-weight:600; line-height:1.15; }
.ap-beat { order:2; margin:0; font-family:var(--f-ui); font-size:13px; line-height:1.4; color:var(--ink); }
.ap-beat:empty { display:none; }
.ap-buttons { order:3; display:grid; grid-template-columns:34px minmax(68px,1fr) 34px auto auto; gap:4px; }
.ap-buttons button { border:1px solid var(--rule); border-radius:3px; background:var(--paper); padding:6px 7px; min-width:0; min-height:36px; cursor:pointer; font-size:13px; line-height:1.25; }
.ap-buttons .ap-primary { background:var(--ink); color:var(--paper); border-color:var(--ink); }
.ap-buttons button:disabled { opacity:.45; cursor:default; }
.ap-scrub { order:4; display:grid; grid-template-columns:auto minmax(0,1fr); gap:9px; align-items:center; }
#ap-progress { width:100%; min-width:0; height:24px; accent-color:var(--red); margin:0; cursor:pointer; }
.ap-scene-details { order:5; border-top:1px solid var(--rule); border-bottom:1px solid var(--rule); }
.ap-selectors { order:6; display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:8px; }
.ap-selectors > div { min-width:0; }
.ap-selectors .ap-label { margin-bottom:4px; }
.ap-options-details { order:8; }
.playback summary { padding:7px 0; min-height:32px; cursor:pointer; font-family:var(--f-ui); font-size:13px; line-height:1.35; color:var(--ink); }
.playback details[open] > summary { margin-bottom:4px; }
.ap-options-content { display:flex; flex-direction:column; gap:10px; padding-bottom:4px; }
.ap-options { display:flex; flex-wrap:wrap; align-items:center; gap:8px 14px; font-size:13px; }
.ap-options label { display:flex; align-items:center; gap:5px; }
.ap-options select { width:auto; padding:4px; }
.playback input[type=checkbox] { accent-color:var(--red); }
.ap-limit { order:7; font-size:12px; line-height:1.4; color:var(--muted); }
.ap-limit:empty { display:none; }
.ap-scene-reading { font-family:var(--f-text); font-size:15px; line-height:1.5; padding-bottom:10px; overflow-wrap:break-word; }
.ap-scene-reading p { margin:0 0 8px; }
.ap-scene-reading .ap-source { font-family:var(--f-ui); font-size:12px; line-height:1.4; color:var(--muted); margin:9px 0 0; }
.ap-scene-reading figure { margin:10px 0 0; padding-left:11px; border-left:2px solid var(--rule); }
.ap-scene-reading blockquote { margin:0; font-size:15px; }
.ap-scene-reading blockquote p { margin:0 0 .5em; }
.ap-scene-reading figcaption { font-family:var(--f-ui); font-size:12px; line-height:1.4; color:var(--muted); }
.ap-key { font-size:12px; line-height:1.4; color:var(--muted); margin:0; display:flex; align-items:center; gap:5px; }
.ap-key span { width:8px; height:8px; display:inline-block; border-radius:50%; }
.ap-key-red { background:var(--red); } .ap-key-brown { background:var(--brown); margin-left:10px; }
.ap-method { font-size:12px; line-height:1.4; }
.ap-overlay { pointer-events:none; }
.ap-actor-label { font-family:var(--f-ui); font-size:12px; font-weight:600; paint-order:stroke; stroke:var(--panel); stroke-width:3px; stroke-linejoin:round; fill:var(--ink); }
.ap-label-leader { fill:none; stroke:var(--muted); stroke-width:1px; opacity:.6; vector-effect:non-scaling-stroke; }
.ap-actor-body { stroke:var(--panel); stroke-width:1.5px; }
.ap-trace { fill:none; stroke:var(--water); stroke-width:3; vector-effect:non-scaling-stroke; opacity:.8; stroke-linecap:round; }
.ap-position-ring { fill:none; stroke:var(--water); stroke-width:1.4; opacity:.65; }
.ap-map-label { position:absolute; left:10px; bottom:10px; padding:5px 8px; max-width:calc(100% - 20px); background:var(--panel); border:1px solid var(--rule); border-radius:3px; font-size:12px; pointer-events:none; }
@media(max-width:860px) {
  .panel section.playback { gap:6px; }
  .ap-caption .ap-title { font-size:18px; order:3; }
  .ap-caption .ap-beat { order:4; }
  .ap-buttons { order:1; grid-template-columns:34px minmax(68px,1fr) 34px auto auto; }
  .ap-scrub { order:2; }
  .ap-buttons button { min-height:40px; }
  .playback summary { min-height:36px; padding-block:8px; }
  .ap-selectors select { min-height:36px; font-size:13px; }
  .ap-options { gap:9px; }
}
